mapper.select:
SELECT id as testCaseId, task_id as taskId, task_name as taskName, test_case_name as testCaseName, test_target as testTarget, test_type as testType, priority, description, precondition, test_data as testData, test_steps as testSteps, expected_result as expectedResult, actual_result as actualResult, test_status as testStatus, execution_date as executionDate, duration, notes, requirements, assignee, assigneeName, is_deleted as isDeleted, created_at as createdAt, updated_at as updatedAt, created_by as createdBy, updated_by as updatedBy, pjt_id as pjtId FROM ( SELECT S.*, CEIL( (@ROWNUM:=@ROWNUM+1) / #{pageSize} ) AS PAGE FROM ( SELECT ut.id, ut.task_id, ut.task_name, ut.test_case_name, ut.test_target, ut.test_type, ut.priority, ut.description, ut.precondition, ut.test_data, ut.test_steps, ut.expected_result, ut.actual_result, ut.test_status, ut.execution_date, ut.duration, ut.notes, ut.requirements, ut.assignee, ut.is_deleted, ut.created_at, ut.updated_at, ut.created_by, ut.updated_by, ut.pjt_id, COALESCE(u.name, ut.assignee) as assigneeName FROM unit_test_case ut LEFT JOIN users u ON ut.assignee = u.user_id WHERE ut.is_deleted = 'N'
AND ut.task_id LIKE CONCAT('%', #{searchTaskId}, '%')
AND ut.test_status = #{searchTestStatus}
AND (ut.assignee LIKE CONCAT('%', #{searchAssignee}, '%') OR u.name LIKE CONCAT('%', #{searchAssignee}, '%'))
AND ut.test_case_name LIKE CONCAT('%', #{searchTestCaseName}, '%')
AND ut.test_target LIKE CONCAT('%', #{searchTestTarget}, '%')
AND ut.test_type = #{searchTestType}
AND ut.priority = #{searchPriority}
AND DATE(ut.created_at) >= #{dateFrom}
AND DATE(ut.created_at) <= #{dateTo}
AND ut.pjt_id = #{pjtId}
ORDER BY ut.id DESC ) S, (SELECT @ROWNUM := 0) TMP ) A WHERE PAGE = #{pageIndex}

SELECT COUNT(*)
FROM unit_test_case ut
LEFT JOIN users u ON ut.assignee = u.user_id
WHERE ut.is_deleted = 'N'

    AND ut.task_id LIKE CONCAT('%', #{searchTaskId}, '%')


    AND ut.test_status = #{searchTestStatus}


    AND (ut.assignee LIKE CONCAT('%', #{searchAssignee}, '%') OR u.name LIKE CONCAT('%', #{searchAssignee}, '%'))


    AND ut.test_case_name LIKE CONCAT('%', #{searchTestCaseName}, '%')


    AND ut.test_target LIKE CONCAT('%', #{searchTestTarget}, '%')


    AND ut.test_type = #{searchTestType}


    AND ut.priority = #{searchPriority}


    AND DATE(ut.created_at) >= #{dateFrom}


    AND DATE(ut.created_at) <= #{dateTo}


    AND ut.pjt_id = #{pjtId}

mapper.update:
UPDATE unit_test_case 
SET 
    is_deleted = 'Y',
    updated_at = NOW(),
    updated_by = #{updatedBy}
WHERE id = #{testCaseId}

mapper.select:
SELECT test_status as testStatus, COUNT(*) as cnt FROM unit_test_case WHERE is_deleted = 'N'
AND pjt_id = #{pjtId}
GROUP BY test_status

SELECT ut.assignee, COALESCE(u.name, ut.assignee) as assigneeName, COUNT(*) as count FROM unit_test_case ut LEFT JOIN users u ON ut.assignee = u.user_id WHERE ut.is_deleted = 'N'
AND ut.pjt_id = #{pjtId}
GROUP BY ut.assignee, u.name ORDER BY count DESC

SELECT priority, COUNT(*) as count FROM unit_test_case WHERE is_deleted = 'N'
AND pjt_id = #{pjtId}
GROUP BY priority ORDER BY CASE priority WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 WHEN 'LOW' THEN 3 ELSE 4 END

SELECT test_type as testType, COUNT(*) as count FROM unit_test_case WHERE is_deleted = 'N'
AND pjt_id = #{pjtId}
GROUP BY test_type ORDER BY count DESC

SELECT DATE(execution_date) as executionDate, COUNT(*) as totalCount, SUM(CASE WHEN test_status = 'SUC' THEN 1 ELSE 0 END) as successCount, SUM(CASE WHEN test_status = 'FAI' THEN 1 ELSE 0 END) as failCount FROM unit_test_case WHERE is_deleted = 'N' AND execution_date IS NOT NULL
AND DATE(execution_date) >= #{dateFrom}
AND DATE(execution_date) <= #{dateTo}
AND pjt_id = #{pjtId}
GROUP BY DATE(execution_date) ORDER BY execution_date DESC

SELECT test_type as testType, COUNT(*) as totalCount, SUM(CASE WHEN test_status IN ('SUC', 'FAI') THEN 1 ELSE 0 END) as completedCount, ROUND(SUM(CASE WHEN test_status IN ('SUC', 'FAI') THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) as coverageRate FROM unit_test_case WHERE is_deleted = 'N'
AND pjt_id = #{pjtId}
GROUP BY test_type ORDER BY coverageRate DESC

SELECT COUNT(*)
FROM unit_test_case 
WHERE test_case_name = #{testCaseName}
AND test_target = #{testTarget}
AND is_deleted = 'N'


    AND id != #{testCaseId}



    AND pjt_id = #{pjtId}

SELECT task_id as taskId, task_name as taskName, COUNT(*) as count FROM unit_test_case WHERE is_deleted = 'N'
AND pjt_id = #{pjtId}
GROUP BY task_id, task_name ORDER BY count DESC
